INSERT OR REPLACE INTO "Subject" ("id", "name", "code", "sectionType", "description", "isActive", "order", "createdAt") VALUES ('cmvujfpmo0000pj85qeni7e8e', 'English', 'ENG', 'LANGUAGE', 'CUET UG English language section', 1, 4, '2026-10-30T05:34:53.568Z');

INSERT OR REPLACE INTO "Passage" ("id", "examId", "passageKey", "title", "content", "sourcePageStart", "sourcePageEnd", "createdAt") VALUES ('3031020d-ba2a-59d4-9ee6-47bef7407933', '63bd7582-96b1-5eef-bbfc-803ac5c6d8ed', 'michael_van_rescue', 'Michael in the stranded van', 'Thanks to the angle of the van and the injuries Michael had sustained, just opening a door and clambering out of the vehicle seemed an insurmountable challenge, never mind climbing up 145 feet of steep, rugged terrain. He''d have to rely on being rescued. But that wouldn''t be easy. Michael could hear cars whizzing past on the road above, but even if passersby happened to glimpse his vehicle amid the shoulder-high brush, apparently abandoned, they wouldn''t be able to see anyone inside. He had no cellphones-Michael had never seen the point of getting one. No one knew he''d had taken an unplanned drive out of Victoria, so they''d have no reason to look for him here. And he couldn''t honk to get the attention of drivers on the highway. In the 19years that he''d owned his van, the horn had never worked. On the plus side, he was dry, at least for the most part. It was cold in the van, but he had an extra fleece-ironically, emblazoned with ''Live the adventure, live the dream." To sustain himself, he had scattered roasted veggies, the bread which was now inedible, but he had a bag of mini chocolate bars. To drink he had one water bottle. He apportioned out his stash and switched on his hazard lights, hoping someone would spot him from the highway above. It was a false hope. He didn''t realize that his off road descent had ripped the wires off the van''s undercarriage.', 1, 2, '2026-10-30T05:34:53.584Z');
INSERT OR REPLACE INTO "Passage" ("id", "examId", "passageKey", "title", "content", "sourcePageStart", "sourcePageEnd", "createdAt") VALUES ('c2a0325d-2c64-599f-a647-b4dccf0d1aa2', '63bd7582-96b1-5eef-bbfc-803ac5c6d8ed', 'nutrition_guidelines', 'Indian nutrition guidelines', 'The INTERNET is flooded with wisdom on nutrition, be it weight-loss diets, intermittent fasting, veganism, giving up carbohydrates or taking supplements. The truth is, it is difficult to find a balanced meal that works for you from the information swirling around you. That''s why the National Institute of Nutrition (NIN), under the aegis of the Indian Council of Medical Research (ICMR), has released a comprehensive guideline on how Indians should be eating clean with easily accessible resources and, most importantly, what suits their body type. Complete with an ideal plate, diet charts, recipes and advisories on how you should be cooking and in what cookware, this is an essential handbook that all of us would find convenient to incorporate into our daily lives. Given India''s growing burden of non- communicable diseases, these guidelines are significant as they lay down the template of foundational nutrition in children, beginning with pregnant women. The report says that proper nutrition for a mother and child is linked not only to proper growth and development but also to the risk of diabetes, hypertension and heart attack later in life. Over 56 percent of all non-communicable diseases can be attributed to an unhealthy diet. As the reports show, a healthy diet can prevent 80 percent of type 2 diabetes and significantly reduce the burden of heart disease, high blood pressure and prevent premature deaths. It has even warned against taking supplements for building body mass and recommended restricting salt intake, minimizing sugar and ultra-processed foods and reading information on food labels correctly.', 10, 11, '2026-10-30T05:34:53.587Z');
INSERT OR REPLACE INTO "Passage" ("id", "examId", "passageKey", "title", "content", "sourcePageStart", "sourcePageEnd", "createdAt") VALUES ('fa6e4a77-676d-56f0-a8fa-7728356b9f82', '63bd7582-96b1-5eef-bbfc-803ac5c6d8ed', 'indian_english_literature', 'Indian Writing in English', 'The seed of Indian Writing in English was sown during the period of the British rule in India. Now the seed has blossomed into an evergreen tree, with fragrant flowers and ripe fruits. The fruits are being tasted not only by the native people, but they are also being ''chewed and digested'' by the foreigners. It happened only after constant care, pruning and feeding. Indian English Literature is an honest enterprise to demonstrate the ever rare gems of Indian Writing in English. From being a singular and exceptional, rather gradual native flare - up of geniuses, Indian Writing has turned out to be a new form of Indian culture and voice in which India converses regularly. Indian writers - poets, novelists, essayists, and dramatists have been making momentous and considerable contributions to world literature since the Pre - Independence era. The past few years have witnessed a gigantic prospering and thriving of Indian English Writing in the global market. Indian English Literature has attained an independent status in the realm of world literature. Wide ranges of themes are dealt with by Indian writing in English. While this literature continues to reflect Indian culture, tradition, social values and even Indian history through the depiction of life in India and Indians living elsewhere, recent Indian English fiction has been trying to give expression to the Indian experience of modern predicaments.', 19, 20, '2026-10-30T05:34:53.592Z');

INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('292bc7b8-5521-5da5-b7e0-031e35e2c751', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Michael didn''t have much hope of being rescued by the passers-by because of ____.', NULL, '[{"id":"opt-292bc7b8-5521-5da5-b7e0-031e35e2c751-1","text":"the rugged terrain"},{"id":"opt-292bc7b8-5521-5da5-b7e0-031e35e2c751-2","text":"the high foliage which obstructed the view"},{"id":"opt-292bc7b8-5521-5da5-b7e0-031e35e2c751-3","text":"the injuries that he had sustained"},{"id":"opt-292bc7b8-5521-5da5-b7e0-031e35e2c751-4","text":"the angle of the vehicle"}]', NULL, 'B', 'The passage states that even if passersby happened to glimpse the vehicle, it was amid "shoulder-high
brush," which means the high foliage was the direct obstruction preventing them from spotting the van
easily or seeing Michael inside.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.596Z', '2026-10-30T05:34:53.596Z', 1, '3031020d-ba2a-59d4-9ee6-47bef7407933', 'michael_van_rescue', 2, 'B', 'source_key_recorded', NULL, 1, 3, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('ebcfa325-0acc-54fa-a336-bb45cbf81662', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', '''He apportioned out his stash..'', what does the word stash as mentioned in the passage refer to:-', NULL, '[{"id":"opt-ebcfa325-0acc-54fa-a336-bb45cbf81662-1","text":"Money"},{"id":"opt-ebcfa325-0acc-54fa-a336-bb45cbf81662-2","text":"Food"},{"id":"opt-ebcfa325-0acc-54fa-a336-bb45cbf81662-3","text":"Injuries"},{"id":"opt-ebcfa325-0acc-54fa-a336-bb45cbf81662-4","text":"Fleece"}]', NULL, 'B', 'Stash (as a noun, which is how it''s used in the sentence "He apportioned out his stash...") means a secret
store or hidden supply of something.

In the context of the passage, Michael''s "stash" refers to his hidden supply of food and drink.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.603Z', '2026-10-30T05:34:53.603Z', 2, '3031020d-ba2a-59d4-9ee6-47bef7407933', 'michael_van_rescue', 2, 'B', 'source_key_recorded', NULL, 3, 5, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('a241d577-5290-5566-ac4a-f927f343b904', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Michael thinks that nobody would look for him because ___.', NULL, '[{"id":"opt-a241d577-5290-5566-ac4a-f927f343b904-1","text":"the trip was unplanned"},{"id":"opt-a241d577-5290-5566-ac4a-f927f343b904-2","text":"he had no friends"},{"id":"opt-a241d577-5290-5566-ac4a-f927f343b904-3","text":"he never liked any attention"},{"id":"opt-a241d577-5290-5566-ac4a-f927f343b904-4","text":"his horn was not working"}]', NULL, 'A', 'The passage states: "He had no cellphones-Michael had never seen the point of getting one. No one knew
he''d taken an unplanned drive out of Victoria, so they''d have no reason to look for him here.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.607Z', '2026-10-30T05:34:53.607Z', 3, '3031020d-ba2a-59d4-9ee6-47bef7407933', 'michael_van_rescue', 1, 'A', 'source_key_recorded', NULL, 5, 7, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('d5bd352c-4b5b-547b-805e-71eea055c6a3', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'The slogan on the soft blanket was ironical as _____.', NULL, '[{"id":"opt-d5bd352c-4b5b-547b-805e-71eea055c6a3-1","text":"he was living the adventure in reality."},{"id":"opt-d5bd352c-4b5b-547b-805e-71eea055c6a3-2","text":"his dream had come true."},{"id":"opt-d5bd352c-4b5b-547b-805e-71eea055c6a3-3","text":"he had always dreamed of being in an accident."},{"id":"opt-d5bd352c-4b5b-547b-805e-71eea055c6a3-4","text":"he was confronting a near-fatal situation."}]', NULL, 'D', '"Live the adventure, live the dream" is a slogan that suggests excitement, happiness, and a highly
desirable, positive experience.
The Reality (The Irony): Michael is injured, trapped in an angled van, in a difficult location, with no
way to call for help, facing an "insurmountable challenge" just to get out, and confronting a situation
that is potentially fatal. This is the opposite of a desirable "adventure" or "dream."', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.612Z', '2026-10-30T05:34:53.612Z', 4, '3031020d-ba2a-59d4-9ee6-47bef7407933', 'michael_van_rescue', 4, 'D', 'source_key_recorded', NULL, 7, 9, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('5ee8a982-a8bc-58c7-8367-e16eda79c922', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'The guidelines on how Indians should eat were released because:-', NULL, '[{"id":"opt-5ee8a982-a8bc-58c7-8367-e16eda79c922-1","text":"NIN was flooded with requests from people for some guidelines."},{"id":"opt-5ee8a982-a8bc-58c7-8367-e16eda79c922-2","text":"It was becoming difficult to find a balanced meal from the information available."},{"id":"opt-5ee8a982-a8bc-58c7-8367-e16eda79c922-3","text":"ICMR pressured NIN to release the guidelines on what people should eat."},{"id":"opt-5ee8a982-a8bc-58c7-8367-e16eda79c922-4","text":"ICMR wanted to take over the responsibility for the health of an average Indian."}]', NULL, 'B', 'The passage clearly states that the internet is "flooded with wisdom on nutrition," but that this information
makes it "difficult to find a balanced meal that works for you." The National Institute of Nutrition (NIN)
released the guidelines specifically to give people a "comprehensive" and clear handbook on healthy eating
to reduce this confusion and solve the information overload problem.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.617Z', '2026-10-30T05:34:53.617Z', 5, 'c2a0325d-2c64-599f-a647-b4dccf0d1aa2', 'nutrition_guidelines', 2, 'B', 'source_key_recorded', NULL, 9, 12, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('890f9317-b274-5943-9b19-01f31c1fe1b5', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Identify the word closest in meaning to the word aegis as used in the passage:-', NULL, '[{"id":"opt-890f9317-b274-5943-9b19-01f31c1fe1b5-1","text":"control"},{"id":"opt-890f9317-b274-5943-9b19-01f31c1fe1b5-2","text":"support"},{"id":"opt-890f9317-b274-5943-9b19-01f31c1fe1b5-3","text":"foundation"},{"id":"opt-890f9317-b274-5943-9b19-01f31c1fe1b5-4","text":"enforcement"}]', NULL, 'B', 'In the phrase, "under the aegis of the Indian Council of Medical Research (ICMR)," aegis means support,
sponsorship, or protection. It clarifies that the National Institute of Nutrition (NIN) released the guidelines
with the official backing and authority of the ICMR, which is the main medical research body in India.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.622Z', '2026-10-30T05:34:53.622Z', 6, 'c2a0325d-2c64-599f-a647-b4dccf0d1aa2', 'nutrition_guidelines', 2, 'B', 'source_key_recorded', NULL, 12, 14, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('57371476-d002-578f-9d32-81cf6fb05290', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'NIN recommends reading the information on labels correctly as:-', NULL, '[{"id":"opt-57371476-d002-578f-9d32-81cf6fb05290-1","text":"People''s knowledge of nutritional facts will increase."},{"id":"opt-57371476-d002-578f-9d32-81cf6fb05290-2","text":"The marketing strategy of manufacturers goes hand in hand with the NIN guidelines."},{"id":"opt-57371476-d002-578f-9d32-81cf6fb05290-3","text":"The endorsement by the celebrities makes the product more salable."},{"id":"opt-57371476-d002-578f-9d32-81cf6fb05290-4","text":"The claims made by manufacturers about the product can be deceptive."}]', NULL, 'D', 'NIN recommends reading labels because the claims made by manufacturers about the product can be
deceptive. This ensures consumers can look past marketing and know the actual ingredients to make healthy
choices', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.627Z', '2026-10-30T05:34:53.627Z', 7, 'c2a0325d-2c64-599f-a647-b4dccf0d1aa2', 'nutrition_guidelines', 4, 'D', 'source_key_recorded', NULL, 14, 16, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('5f4568ea-a199-55bd-b312-086203b804dc', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'The guidelines on how Indians should eat issued by NIN are important as:-', NULL, '[{"id":"opt-5f4568ea-a199-55bd-b312-086203b804dc-1","text":"They lay down the structure of the basic nutrition needs of an average Indian."},{"id":"opt-5f4568ea-a199-55bd-b312-086203b804dc-2","text":"They focus on how to prevent non-communicable diseases among Indians"},{"id":"opt-5f4568ea-a199-55bd-b312-086203b804dc-3","text":"They provide guidance on how to live our lives."},{"id":"opt-5f4568ea-a199-55bd-b312-086203b804dc-4","text":"They direct parents on how to bring up their children."}]', NULL, 'A', 'The passage emphasizes the significance of the guidelines because of "India''s growing burden of non-
communicable diseases" (NCDs). The report specifically notes that a healthy diet based on these guidelines
can prevent 80% of type 2 diabetes and significantly reduce the burden of heart disease, highlighting their
primary goal is disease prevention.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.633Z', '2026-10-30T05:34:53.633Z', 8, 'c2a0325d-2c64-599f-a647-b4dccf0d1aa2', 'nutrition_guidelines', 1, 'A', 'needs_manual_review', 'Printed answer key says A (choice 1), but the solution says disease prevention is the primary goal, which aligns with choice 2. Source conflict; answer not silently changed.', 16, 18, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('c7814ab8-71e2-518d-85d7-44efd1af89fc', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Choose the word that is opposite in meaning of the underlined word :- Indian writers-poets, novelists ,essayists, and dramatists have been making ‘momentous’ and considerable contributions to world literature.', NULL, '[{"id":"opt-c7814ab8-71e2-518d-85d7-44efd1af89fc-1","text":"consequential"},{"id":"opt-c7814ab8-71e2-518d-85d7-44efd1af89fc-2","text":"insignificant"},{"id":"opt-c7814ab8-71e2-518d-85d7-44efd1af89fc-3","text":"pivotal"},{"id":"opt-c7814ab8-71e2-518d-85d7-44efd1af89fc-4","text":"mediocre"}]', NULL, 'B', 'The word momentous means of great importance. Its opposite is insignificant, meaning unimportant.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.640Z', '2026-10-30T05:34:53.640Z', 9, 'fa6e4a77-676d-56f0-a8fa-7728356b9f82', 'indian_english_literature', 2, 'B', 'source_key_recorded', NULL, 19, 21, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('6077db7b-6889-553c-be91-0310a4d5cf19', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Indian writers have been making considerable contributions to world literature since:-', NULL, '[{"id":"opt-6077db7b-6889-553c-be91-0310a4d5cf19-1","text":"Indian English Writing has entered the global market."},{"id":"opt-6077db7b-6889-553c-be91-0310a4d5cf19-2","text":"it attained an independent status in the realm of World Literature."},{"id":"opt-6077db7b-6889-553c-be91-0310a4d5cf19-3","text":"Pre-Independence era"},{"id":"opt-6077db7b-6889-553c-be91-0310a4d5cf19-4","text":"the past few years"}]', NULL, 'C', 'The passage explicitly states that Indian writers have been making contributions to world literature "since the
Pre-Independence era."', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.646Z', '2026-10-30T05:34:53.646Z', 10, 'fa6e4a77-676d-56f0-a8fa-7728356b9f82', 'indian_english_literature', 3, 'C', 'source_key_recorded', NULL, 21, 23, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('1c81b527-4da6-514b-88f6-5185536cd84f', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'What does the enterprise of Indian English Literature exhibit?', NULL, '[{"id":"opt-1c81b527-4da6-514b-88f6-5185536cd84f-1","text":"How Indian writing in English enjoys foreign readership."},{"id":"opt-1c81b527-4da6-514b-88f6-5185536cd84f-2","text":"Its attainment of an independent status in the realm of world Literature"},{"id":"opt-1c81b527-4da6-514b-88f6-5185536cd84f-3","text":"How it is prospering and thriving in the global market"},{"id":"opt-1c81b527-4da6-514b-88f6-5185536cd84f-4","text":"The ever rare gems of Indian Writing in English"}]', NULL, 'D', 'The text defines Indian English Literature as "an honest enterprise to demonstrate the ever rare gems of
Indian Writing in English."', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.652Z', '2026-10-30T05:34:53.652Z', 11, 'fa6e4a77-676d-56f0-a8fa-7728356b9f82', 'indian_english_literature', 4, 'D', 'source_key_recorded', NULL, 23, 25, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('1cde9bf9-22df-5ed3-870e-7c1fe1655891', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'According to the passage, Indian Writing in English dealt with the themes of:- (A) how the seed of Indian writing in English was sown during colonial rule. (B) Indian culture, tradition and social values (C) Indian history through the depiction of life in India and Indians living elsewhere (D) Indian experience of modern predicaments.', NULL, '[{"id":"opt-1cde9bf9-22df-5ed3-870e-7c1fe1655891-1","text":"(A), (B) and (D) only"},{"id":"opt-1cde9bf9-22df-5ed3-870e-7c1fe1655891-2","text":"(B), (C) and (D) only"},{"id":"opt-1cde9bf9-22df-5ed3-870e-7c1fe1655891-3","text":"(B) and (D) only"},{"id":"opt-1cde9bf9-22df-5ed3-870e-7c1fe1655891-4","text":"(C) and (D) only"}]', NULL, 'B', 'The final paragraph lists the themes: Indian culture, tradition, social values (B), Indian history (C), and
the Indian experience of modern predicaments (D). Option (A) refers to the history of the writing, not its
themes.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.657Z', '2026-10-30T05:34:53.657Z', 12, 'fa6e4a77-676d-56f0-a8fa-7728356b9f82', 'indian_english_literature', 2, 'B', 'source_key_recorded', NULL, 25, 27, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('2693a7ea-a886-59ac-bce5-36874549cbb1', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Rearrange the given parts to form a meaningful sentence:-

(A) people still struggle to balance their personal

(B) despite the advancements in technology, many

(C) often leading to stress and burnout

(D) live with their professional commitments', NULL, '[{"id":"opt-2693a7ea-a886-59ac-bce5-36874549cbb1-1","text":"(D), (B), (C), (A)"},{"id":"opt-2693a7ea-a886-59ac-bce5-36874549cbb1-2","text":"(A), (B), (C), (D)"},{"id":"opt-2693a7ea-a886-59ac-bce5-36874549cbb1-3","text":"(B), (A), (D), (C)"},{"id":"opt-2693a7ea-a886-59ac-bce5-36874549cbb1-4","text":"(C), (B), (D), (A)"}]', NULL, 'C', 'The full, coherent sentence is: Despite the advancements in technology, many people still struggle to
balance their personal live with their professional commitments, often leading to stress and burnout.

Therefore, the correct option is 3. (B), (A), (D), (C).', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.662Z', '2026-10-30T05:34:53.662Z', 13, NULL, NULL, 3, 'C', 'source_key_recorded', NULL, 27, 28, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('0739daeb-4134-5b35-b24e-589b4a694fdf', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Rearrange the following parts to form a meaningful sentence:-

(A) the role of sound sleep in memory consolidation and

