INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('340e1765-0479-519b-9be8-d774286838fe', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Rearrange the given parts to form a meaningful sentence:-

(A) disturbances, and decreased productivity

(B) although mobile phones have revolutionized

(C) communication, excessive usage can lead to

(D) various health issues, including eye strain, sleep', NULL, '[{"id":"opt-340e1765-0479-519b-9be8-d774286838fe-1","text":"(D), (A), (B), (C)"},{"id":"opt-340e1765-0479-519b-9be8-d774286838fe-2","text":"(B), (C), (D), (A)"},{"id":"opt-340e1765-0479-519b-9be8-d774286838fe-3","text":"(B), (A), (D), (C)"},{"id":"opt-340e1765-0479-519b-9be8-d774286838fe-4","text":"(C), (B), (D), (A)"}]', NULL, 'B', 'The coherent sentence formed is :

Although mobile phones have revolutionized communication, excessive usage can lead to various health
issues, including eye strain, sleep disturbances, and decreased productivity.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.672Z', '2026-10-30T05:34:53.672Z', 15, NULL, NULL, 2, 'B', 'source_key_recorded', NULL, 29, 30, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('c7133958-0409-533c-aa61-5fa75fd84f71', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Fill in the blanks in the sentences given in List-I with the verb forms
