INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('2b755634-5015-50fd-be94-02b0414433a3', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Select the most appropriate option to fill in the blank in the
following sentence:-

A person who eats too much is a/an_________', NULL, '[{"id":"opt-2b755634-5015-50fd-be94-02b0414433a3-1","text":"glutton"},{"id":"opt-2b755634-5015-50fd-be94-02b0414433a3-2","text":"epicure"},{"id":"opt-2b755634-5015-50fd-be94-02b0414433a3-3","text":"gourmand"},{"id":"opt-2b755634-5015-50fd-be94-02b0414433a3-4","text":"pagan"}]', NULL, 'A', 'A glutton is a person who consumes excessively or habitually, especially of food and drink.

The term often carries a negative connotation, implying greed or overindulgence.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.689Z', '2026-10-30T05:34:53.689Z', 19, NULL, NULL, 1, 'A', 'source_key_recorded', NULL, 33, 34, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('30fed7bb-f7ca-5a0c-a2f2-c5f03a838625', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Choose the most appropriate word to fill in the blank in the
following sentence:-

The unprecedented display of remarkable innovation and creativity
_______ him into an enviable position.', NULL, '[{"id":"opt-30fed7bb-f7ca-5a0c-a2f2-c5f03a838625-1","text":"catapulted"},{"id":"opt-30fed7bb-f7ca-5a0c-a2f2-c5f03a838625-2","text":"capsized"},{"id":"opt-30fed7bb-f7ca-5a0c-a2f2-c5f03a838625-3","text":"condemned"},{"id":"opt-30fed7bb-f7ca-5a0c-a2f2-c5f03a838625-4","text":"commemorated"}]', NULL, 'A', 'Catapulted (meaning to hurl or launch suddenly) is the best fit, as the innovation propelled him into a
good position.
Capsized means to overturn (a boat);
Condemned means to officially declare unfit or to express strong disapproval;
Commemorated means to recall and show respect for.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.694Z', '2026-10-30T05:34:53.694Z', 20, NULL, NULL, 1, 'A', 'source_key_recorded', NULL, 34, 34, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('dea968f6-b8a1-54c6-ad02-7cc3d2e8f281', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Identify the word closest in meaning to the underlined word:-

What are you trying to ‘insinuate’ through this message?', NULL, '[{"id":"opt-dea968f6-b8a1-54c6-ad02-7cc3d2e8f281-1","text":"Express"},{"id":"opt-dea968f6-b8a1-54c6-ad02-7cc3d2e8f281-2","text":"Affirm"},{"id":"opt-dea968f6-b8a1-54c6-ad02-7cc3d2e8f281-3","text":"Allude"},{"id":"opt-dea968f6-b8a1-54c6-ad02-7cc3d2e8f281-4","text":"Propagate"}]', NULL, 'C', 'To insinuate means to suggest or hint at something bad or derogatory in an indirect and unpleasant way.

The closest synonym is Allude, which means to hint at.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.698Z', '2026-10-30T05:34:53.698Z', 21, NULL, NULL, 3, 'C', 'source_key_recorded', NULL, 35, 35, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('358bc918-2f94-5fcf-8ba2-a1b0e0525544', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Rearrange the given parts to form a meaningful sentence:-

(A) while their white coats provide camouflage from

(B) predators and help them silently approach prey

(C) stay warm with thick fur, insulated feet, and fluffy tails,

(D) arctic foxes, adapted to the harsh Arctic winter,', NULL, '[{"id":"opt-358bc918-2f94-5fcf-8ba2-a1b0e0525544-1","text":"(A), (D), (C), (B)"},{"id":"opt-358bc918-2f94-5fcf-8ba2-a1b0e0525544-2","text":"(D), (A), (C), (B)"},{"id":"opt-358bc918-2f94-5fcf-8ba2-a1b0e0525544-3","text":"(D), (C), (A), (B)"},{"id":"opt-358bc918-2f94-5fcf-8ba2-a1b0e0525544-4","text":"(C), (B), (D), (A)"}]', NULL, 'C', 'The coherent sentence formed is :
Arctic foxes, adapted to the harsh Arctic winter, stay warm with thick fur, insulated feet, and fluffy
tails, while their white coats provide camouflage from predators and help them silently approach prey .', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.703Z', '2026-10-30T05:34:53.703Z', 22, NULL, NULL, 3, 'C', 'source_key_recorded', NULL, 35, 36, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('ed6b484e-7ddd-5519-ae96-de0d668870ff', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Select the word closest in meaning to the word: Petulant', NULL, '[{"id":"opt-ed6b484e-7ddd-5519-ae96-de0d668870ff-1","text":"Placid"},{"id":"opt-ed6b484e-7ddd-5519-ae96-de0d668870ff-2","text":"Patient"},{"id":"opt-ed6b484e-7ddd-5519-ae96-de0d668870ff-3","text":"Irritable"},{"id":"opt-ed6b484e-7ddd-5519-ae96-de0d668870ff-4","text":"Insignificant"}]', NULL, 'C', 'Petulant means easily irritated or annoyed, especially over minor issues; childishly sulky or bad-tempered.

The closest synonym is Irritable.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.709Z', '2026-10-30T05:34:53.709Z', 23, NULL, NULL, 3, 'C', 'source_key_recorded', NULL, 36, 37, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('90a2643c-7a9b-560e-bdc7-920d5aa9f193', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Select the most appropriate word or phrase to complete the
following sentence:-

Once you ___into the routine, you will find the work is quite easy.', NULL, '[{"id":"opt-90a2643c-7a9b-560e-bdc7-920d5aa9f193-1","text":"are settled"},{"id":"opt-90a2643c-7a9b-560e-bdc7-920d5aa9f193-2","text":"had settled"},{"id":"opt-90a2643c-7a9b-560e-bdc7-920d5aa9f193-3","text":"settled"},{"id":"opt-90a2643c-7a9b-560e-bdc7-920d5aa9f193-4","text":"will settle"}]', NULL, 'A', 'When a sentence uses a future result ("you will find...") and starts with a time conjunction like
"Once" (or if, when, as soon as), the verb in the "Once" clause must be in the Simple Present tense.
"are settled" is the grammatically correct Simple Present (in the passive voice) needed here. The other
options are incorrect tenses (past perfect, simple past, simple future).', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.715Z', '2026-10-30T05:34:53.715Z', 24, NULL, NULL, 1, 'A', 'source_key_recorded', NULL, 37, 37, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('0b8caa4e-b310-5090-9388-8421e24e2e2c', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Rearrange the following parts to form a meaningful sentence:-

(A) surviving written literature from ancient Mesopotamia because
of

(B) through the ages, including the Iliad and the Odyssey

(C) the Epic of Gilgamesh is often cited as the earliest

(D) its significantly enduring impact on ancient literary works', NULL, '[{"id":"opt-0b8caa4e-b310-5090-9388-8421e24e2e2c-1","text":"(C), (A), (D), (B)"},{"id":"opt-0b8caa4e-b310-5090-9388-8421e24e2e2c-2","text":"(B), (D), (A), (C)"},{"id":"opt-0b8caa4e-b310-5090-9388-8421e24e2e2c-3","text":"(C), (A), (B), (D)"},{"id":"opt-0b8caa4e-b310-5090-9388-8421e24e2e2c-4","text":"(B), (C), (A), (D)"}]', NULL, 'A', 'The coherent sentence formed by the sequence (C), (A), (D), (B) is:

The Epic of Gilgamesh is often cited as the earliest surviving written literature from ancient Mesopotamia
because of its significantly enduring impact on ancient literary works through the ages, including the Iliad

and the Odyssey.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.720Z', '2026-10-30T05:34:53.720Z', 25, NULL, NULL, 1, 'A', 'source_key_recorded', NULL, 38, 38, 'English_2025-05-20_Shift_1.pdf');
