INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('77b44f14-e0d2-539f-b773-a642b439e20e', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Choose the correct word from the options given below to substitute
