INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('429cbb98-2894-5a8b-afaa-4dcd2b0cc862', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Select the most appropriate antonym of the underlined word in the
given sentence:-

It seemed a perfectly ‘innocuous’ remark.', NULL, '[{"id":"opt-429cbb98-2894-5a8b-afaa-4dcd2b0cc862-1","text":"harmless"},{"id":"opt-429cbb98-2894-5a8b-afaa-4dcd2b0cc862-2","text":"insane"},{"id":"opt-429cbb98-2894-5a8b-afaa-4dcd2b0cc862-3","text":"pernicious"},{"id":"opt-429cbb98-2894-5a8b-afaa-4dcd2b0cc862-4","text":"permissible"}]', NULL, 'A', 'The word innocuous means harmless or inoffensive.

Harmless is a synonym.
Pernicious means having a harmful effect, especially in a gradual or subtle way.
Therefore, pernicious is the most appropriate antonym.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.754Z', '2026-10-30T05:34:53.754Z', 32, NULL, NULL, 1, 'A', 'needs_manual_review', 'Printed answer key says A (choice 1, harmless), but the solution identifies pernicious (choice 3) as the antonym of innocuous. Source conflict; answer not silently changed.', 44, 44, 'English_2025-05-20_Shift_1.pdf');
