INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('31a01e8b-be9d-54b5-8da7-bb6a933c95ac', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Select the word or phrase that best completes the following
sentence:-

Desert flowers can be invisible for years__________ appear
suddenly after heavy rain.', NULL, '[{"id":"opt-31a01e8b-be9d-54b5-8da7-bb6a933c95ac-1","text":"alternatively or"},{"id":"opt-31a01e8b-be9d-54b5-8da7-bb6a933c95ac-2","text":"consequently and"},{"id":"opt-31a01e8b-be9d-54b5-8da7-bb6a933c95ac-3","text":"nevertheless, so"},{"id":"opt-31a01e8b-be9d-54b5-8da7-bb6a933c95ac-4","text":"actually, but"}]', NULL, 'D', 'The first blank requires an adverb that acts as a transition or intensifier, introducing a surprising fact about
their invisibility: "actually" fits this.

1. The second blank requires a coordinating conjunction to connect two contrasting actions (being
invisible vs. appearing suddenly): "but" is the correct choice to express this contrast.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.785Z', '2026-10-30T05:34:53.785Z', 38, NULL, NULL, 4, 'D', 'source_key_recorded', NULL, 49, 50, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('062ac410-06d4-56f2-b367-a1fec2c92b92', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Identify the word that is closest in meaning to the word-Relegate', NULL, '[{"id":"opt-062ac410-06d4-56f2-b367-a1fec2c92b92-1","text":"Elevate"},{"id":"opt-062ac410-06d4-56f2-b367-a1fec2c92b92-2","text":"Demote"},{"id":"opt-062ac410-06d4-56f2-b367-a1fec2c92b92-3","text":"Acknowledge"},{"id":"opt-062ac410-06d4-56f2-b367-a1fec2c92b92-4","text":"Celebrate"}]', NULL, 'B', 'Relegate (means to assign to a lower position) & Demote means to move to a less important position, which
is the direct meaning of relegate.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.791Z', '2026-10-30T05:34:53.791Z', 39, NULL, NULL, 2, 'B', 'source_key_recorded', NULL, 50, 51, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('936039f9-6410-58a6-b46a-4793f0465c90', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Complete the sentences given in List-I with the appropriate words
