of being presumptuous.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.810Z', '2026-10-30T05:34:53.810Z', 43, NULL, NULL, 4, 'D', 'source_key_recorded', NULL, 54, 54, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('8b8dfe5d-41c7-5c28-877e-001a9278b432', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Fill in the blank with the most appropriate option in the following
