did not ease the pressure despite the crying.', NULL, 2025, 'CUET UG English 2025 Shift 1', 'medium', 1, 0, 1, '2026-10-30T05:34:53.815Z', '2026-10-30T05:34:53.815Z', 44, NULL, NULL, 4, 'D', 'source_key_recorded', NULL, 54, 55, 'English_2025-05-20_Shift_1.pdf');
INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('40a1bc6f-652a-5eaf-af67-c0f9615d222c', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Select the word opposite in meaning to the word: Resonant', NULL, '[{"id":"opt-40a1bc6f-652a-5eaf-af67-c0f9615d222c-1","text":"Resounding"},{"id":"opt-40a1bc6f-652a-5eaf-af67-c0f9615d222c-2","text":"Cacophonous"},{"id":"opt-40a1bc6f-652a-5eaf-af67-c0f9615d222c-3","text":"Smothered"},{"id":"opt-40a1bc6f-652a-5eaf-af67-c0f9615d222c-4","text":"Pulsating"}]', NULL, 'C', 'Resonant (deep, continuing sound) & Smothered means muffled or suppressed (of sound), which is the
