INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('f4217b18-e4d1-5824-b894-725151c20e09', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Select the word similar in meaning to the word: Scrutiny', NULL, '[{"id":"opt-f4217b18-e4d1-5824-b894-725151c20e09-1","text":"Ignorance"},{"id":"opt-f4217b18-e4d1-5824-b894-725151c20e09-2","text":"Objectivity"},{"id":"opt-f4217b18-e4d1-5824-b894-725151c20e09-3","text":"Oversight"},{"id":"opt-f4217b18-e4d1-5824-b894-725151c20e09-4","text":"Examination"}]', NULL, 'D', 'Scrutiny (critical observation or examination) & Examination is the closest synonym for critical
