INSERT OR REPLACE INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt", "questionNumber", "passageId", "passageKey", "sourceCorrectOptionOrder", "sourceAnswerLabel", "answerReviewStatus", "dataQualityNote", "sourcePageStart", "sourcePageEnd", "sourcePdfFilename") VALUES ('4f3afcbf-d41f-5290-b15b-2360f77b948e', 'cmvujfpmo0000pj85qeni7e8e', NULL, 'single_choice', 'Select the word opposite in meaning to the word: Insufferable', NULL, '[{"id":"opt-4f3afcbf-d41f-5290-b15b-2360f77b948e-1","text":"Painful"},{"id":"opt-4f3afcbf-d41f-5290-b15b-2360f77b948e-2","text":"Deficient"},{"id":"opt-4f3afcbf-d41f-5290-b15b-2360f77b948e-3","text":"Endurable"},{"id":"opt-4f3afcbf-d41f-5290-b15b-2360f77b948e-4","text":"Suppressible"}]', NULL, 'C', 'Insufferable (too extreme or unpleasant to bear) & Endurable means able to be tolerated, the opposite of
